CREATE TABLE "ride_offers" ("id" SERIAL PRIMARY KEY,"ride_id" INTEGER NOT NULL,"driver_id" INTEGER NOT NULL,"status" VARCHAR(20) NOT NULL DEFAULT 'pending',"offered_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expires_at" TIMESTAMP(6) NOT NULL,"responded_at" TIMESTAMP(6),"response_ms" INTEGER,CONSTRAINT "ride_offers_ride_id_fkey" FOREIGN KEY("ride_id") REFERENCES "rides"("id") ON DELETE CASCADE,CONSTRAINT "ride_offers_driver_id_fkey" FOREIGN KEY("driver_id") REFERENCES "driver_profiles"("id") ON DELETE CASCADE,CONSTRAINT "ride_offers_status_check" CHECK("status" IN ('pending','accepted','rejected','expired','cancelled')));
CREATE INDEX "idx_ride_offers_expiry" ON "ride_offers"("status","expires_at"); CREATE INDEX "idx_ride_offers_driver" ON "ride_offers"("driver_id","status","offered_at" DESC); CREATE INDEX "idx_ride_offers_ride" ON "ride_offers"("ride_id","offered_at" DESC);
INSERT INTO "ride_offers" ("ride_id","driver_id","status","offered_at","expires_at","responded_at","response_ms") SELECT "id","driver_id",'accepted',COALESCE("assigned_at","requested_at"),COALESCE("assigned_at","requested_at") + INTERVAL '30 seconds',COALESCE("assigned_at","requested_at"),0 FROM "rides" WHERE "driver_id" IS NOT NULL AND "status" IN ('driver_assigned','driver_arriving','driver_arrived','in_progress');
